CREATE TABLE loan_pricing_proposals (id UUID PRIMARY KEY, application_id UUID NOT NULL REFERENCES loan_applications(id) ON DELETE CASCADE, proposed_by UUID NOT NULL REFERENCES users(id), principal BIGINT NOT NULL CHECK (principal > 0), term_days INTEGER NOT NULL CHECK (term_days BETWEEN 30 AND 365), apr NUMERIC(5,4) NOT NULL CHECK (apr >= 0 AND apr <= 1), interest BIGINT NOT NULL CHECK (interest >= 0), service_fee BIGINT NOT NULL DEFAULT 0 CHECK (service_fee >= 0), other_charges BIGINT NOT NULL DEFAULT 0 CHECK (other_charges >= 0), total BIGINT NOT NULL CHECK (total > 0), fee_breakdown JSONB NOT NULL DEFAULT '[]'::jsonb, status TEXT NOT NULL DEFAULT 'proposed' CHECK (status IN ('proposed','approved','superseded')), created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, approved_by UUID REFERENCES users(id), approved_at TIMESTAMP(3));
CREATE UNIQUE INDEX loan_pricing_proposals_current_idx ON loan_pricing_proposals(application_id) WHERE status IN ('proposed','approved');
